# shellcheck shell=bash
# Renderers: every generated file is a pure function of registry + invites + hub.conf.

hub_host_key() {
  [[ -r $DEVMESH_HOST_KEY_PUB ]] || die "missing hub host key $DEVMESH_HOST_KEY_PUB"
  ssh_key_bare "$(cat "$DEVMESH_HOST_KEY_PUB")"
}

hub_wg_pub() {
  [[ -r $DEVMESH_HUB_KEY ]] || die "missing hub WireGuard key $DEVMESH_HUB_KEY"
  wg pubkey <"$DEVMESH_HUB_KEY"
}

render_wg_hub() {
  local name ip wg_pub
  printf '# Generated by devmesh. Do not edit: run "devmesh apply".\n'
  printf '[Interface]\nAddress = %s/24\nListenPort = %s\nPrivateKey = %s\n' \
    "$HUB_IP" "$WG_PORT" "$(cat "$DEVMESH_HUB_KEY")"
  printf 'PostUp = %s/devmesh-fw up %%i\nPostDown = %s/devmesh-fw down %%i\n' "$DEVMESH_SBIN" "$DEVMESH_SBIN"
  while IFS=$'\t' read -r name _ ip _ _ _ _ _ wg_pub _; do
    printf '\n[Peer]\n# %s\nPublicKey = %s\nAllowedIPs = %s/32\n' "$name" "$wg_pub" "$ip"
  done < <(reg_rows)
}

# Machines' tunnel keys may only open their own reverse port; every device's client
# key may only jump to machine tunnel ports. Forced commands block shells.
# "port-forwarding" re-enables BOTH directions, so each line pins the other one to an
# unusable target (port 1): no -L into the hub's services, no -R squatting a tunnel port.
readonly NO_FWD='"localhost:1"'
render_tunnel_keys() {
  local name kind port client_pub tunnel_pub opens="" line
  printf '# Generated by devmesh. Do not edit.\n'
  while IFS=$'\t' read -r name kind _ port _ _ _ _ _ _ tunnel_pub _; do
    [[ $kind == machine ]] || continue
    printf 'restrict,port-forwarding,permitlisten="localhost:%s",permitopen=%s,command="%s/devmesh-keys-out %s" %s devmesh:%s\n' \
      "$port" "$NO_FWD" "$DEVMESH_SBIN" "$name" "$tunnel_pub" "$name"
    opens+="permitopen=\"localhost:$port\","
  done < <(reg_rows)
  [[ -n $opens ]] || return 0
  while IFS=$'\t' read -r name _ _ _ _ _ _ _ _ client_pub _; do
    line="restrict,port-forwarding,permitlisten=$NO_FWD,${opens}command=\"/bin/false\" $client_pub devmesh:$name"
    printf '%s\n' "$line"
  done < <(reg_rows)
}

render_admin_keys() {
  local name client_pub
  printf '# Generated by devmesh. Do not edit.\n'
  while IFS=$'\t' read -r name _ _ _ _ _ _ _ _ client_pub _; do
    printf 'restrict,command="sudo -n %s/devmesh _ssh %s" %s devmesh:%s\n' \
      "$DEVMESH_SBIN" "$name" "$client_pub" "$name"
  done < <(reg_rows)
}

render_enroll_keys() {
  local code
  printf '# Generated by devmesh. Do not edit.\n'
  while read -r code; do
    [[ -n $code ]] || continue
    invite_load "$code" || continue
    printf 'restrict,expiry-time="%s",command="sudo -n %s/devmesh _enroll %s" %s devmesh-enroll:%s\n' \
      "$(fmt_expiry "$INV_EXPIRES")" "$DEVMESH_SBIN" "$code" "$INV_PUB" "$INV_NAME"
  done < <(invite_codes)
}

# Bare list for nodes that still sync with "keys" (DM_TRUST=open). Once the hub has
# approvers, devices still waiting for approval are not handed out.
render_clients_pub() {
  local name client_pub sig trust=0
  signers_exist && trust=1
  while IFS=$'\t' read -r name _ _ _ _ _ _ _ _ client_pub _ _ _ _ _ sig; do
    ((trust)) && [[ $sig == -* ]] && continue
    printf '%s devmesh:%s\n' "$client_pub" "$name"
  done < <(reg_rows)
}

# Signed bundle for nodes that sync with "keys2" and for "dm refresh" (host keys). The hub
# only repeats signatures made on approvers' devices; it cannot forge any of them.
#   signer <name> <pubkey> <sig-b64|owner>
#   client <name> <pubkey> <sig-b64>
#   host <name> <pubkey> <sig-b64>
#   revoke <name> <pubkey> <sig-b64>     (signed "devmesh-revoke-v1 <name> <pubkey>")
#   epoch <serial> <hash> <signer> <sig-b64>   (signed "devmesh-epoch-v1 <serial> <hash>")
render_bundle() {
  local name kind client_pub host_pub sig csig hsig pub proof
  while IFS=$'\t' read -r name pub proof; do
    printf 'signer %s %s %s\n' "$name" "$pub" "$proof"
  done < <(signers_rows)
  while IFS=$'\t' read -r name kind _ _ _ _ _ _ _ client_pub _ host_pub _ _ _ sig; do
    csig=${sig%%:*}
    hsig=-
    [[ $sig == *:* ]] && hsig=${sig#*:}
    # Only real signatures go out: "-", "owner" and "legacy" are registry markers.
    if valid_sig "$csig"; then printf 'client %s %s %s\n' "$name" "$client_pub" "$csig"; fi
    if [[ $kind == machine ]] && valid_sig "$hsig"; then printf 'host %s %s %s\n' "$name" "$host_pub" "$hsig"; fi
  done < <(reg_rows)
  while IFS=$'\t' read -r name pub proof; do
    printf 'revoke %s %s %s\n' "$name" "$pub" "$proof"
  done < <(revoked_rows)
  if [[ -r $DEVMESH_EPOCH ]]; then
    awk -F'\t' 'NF == 4 {print "epoch " $1 " " $2 " " $3 " " $4}' "$DEVMESH_EPOCH"
  fi
  return 0
}

# hosts: what clients need to list, reach and color devices.
render_hosts() {
  local name kind ip port color user lan mac
  while IFS=$'\t' read -r name kind ip port color user lan mac _; do
    printf '%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\n' "$name" "$kind" "$ip" "$port" "$color" "$user" "$lan" "$mac"
  done < <(reg_rows)
}

render_known_hosts() {
  local name host_pub
  printf '%s,%s %s\n' "$HUB_HOST" "$HUB_IP" "$(hub_host_key)"
  while IFS=$'\t' read -r name _ _ _ _ _ _ _ _ _ _ host_pub _; do
    if [[ $host_pub != - ]]; then
      printf '%s %s\n' "$name" "$host_pub"
    fi
  done < <(reg_rows)
}

# ssh_config for clients. Path A = WireGuard IP; path B = reverse tunnel via hub-jump.
# HostKeyAlias makes both paths share one pinned host key per machine.
render_ssh_config() {
  local name kind ip port user os aliases="hub-admin hub-jump"
  cat <<EOF
# Generated by devmesh. Do not edit: run "dm refresh".
Host hub-admin
  HostName $HUB_HOST
  Port $HUB_SSH_PORT
  User dmadmin
  HostKeyAlias $HUB_HOST
Host hub-jump
  HostName $HUB_HOST
  Port $HUB_SSH_PORT
  User tunnel
  HostKeyAlias $HUB_HOST
EOF
  while IFS=$'\t' read -r name kind ip port _ user _ _ _ _ _ _ _ _ os _; do
    [[ $kind == machine ]] || continue
    if [[ $os == macos ]]; then
      # Its sshd listens on localhost only: path A goes through the hub too.
      cat <<EOF
Host $name
  HostName localhost
  Port $port
  User $user
  HostKeyAlias $name
  ProxyJump hub-jump
EOF
    else
      cat <<EOF
Host $name
  HostName $ip
  User $user
  HostKeyAlias $name
EOF
    fi
    cat <<EOF
Host $name-b
  HostName localhost
  Port $port
  User $user
  HostKeyAlias $name
  ProxyJump hub-jump
EOF
    aliases+=" $name $name-b"
  done < <(reg_rows)
  # Only devmesh aliases: this file is included first in ~/.ssh/config, so a "*" here
  # would hijack known_hosts and identities for every other host (github.com, ...).
  cat <<EOF
Host $aliases
  # The hub's OpenSSH (8.2) has no post-quantum key exchange; silence only that warning
  # on OpenSSH >= 10 (older clients skip the unknown option).
  IgnoreUnknown WarnWeakCrypto
  WarnWeakCrypto no-pq-kex
  IdentityFile ~/.ssh/id_devmesh
  IdentitiesOnly yes
  UserKnownHostsFile ~/.ssh/devmesh_known_hosts
  StrictHostKeyChecking yes
  # A dead link is noticed within ~10 s: shared connections then fail fast (tabs
  # reconnect, probes fall back to path B) instead of hanging on a stale master.
  ServerAliveInterval 5
  ServerAliveCountMax 2
  # One connection per alias, reused for 2 minutes: the live panel asks every few
  # seconds, and through the hub each new handshake costs ~0.5 s. Keyed by the alias only
  # (another alias never reuses it) and short: sockets are limited to ~104 bytes and
  # Termux's home alone is 32 (ssh also appends a 17-byte temporary suffix).
  ControlMaster auto
  ControlPath ~/.ssh/dm-%n
  ControlPersist 120
EOF
}

# Apply live WireGuard config without dropping existing peers.
wg_apply() {
  if wg show "$WG_IFACE" >/dev/null 2>&1; then
    wg syncconf "$WG_IFACE" <(wg-quick strip "$WG_IFACE") || die "wg syncconf failed"
  fi
}

# Render every generated file from the registry, atomically (no live changes).
render_all() {
  lock_acquire
  mkdir -p "$DEVMESH_SSH_KEYS" "$DEVMESH_WG_DIR"
  render_wg_hub | atomic_write "$DEVMESH_WG_DIR/$WG_IFACE.conf" 0600
  render_tunnel_keys | atomic_write "$DEVMESH_SSH_KEYS/tunnel.keys" 0644
  render_admin_keys | atomic_write "$DEVMESH_SSH_KEYS/dmadmin.keys" 0644
  render_enroll_keys | atomic_write "$DEVMESH_SSH_KEYS/enroll.keys" 0644
  render_clients_pub | atomic_write "$DEVMESH_CLIENTS_PUB" 0644
  render_bundle | atomic_write "$DEVMESH_BUNDLE" 0644
}

apply_all() {
  render_all
  wg_apply
}
